"""Movement coefficients assembled from rows generated by the Java bridge.

`tools/generate_coefficient_tables.py` writes `_coefficient_tables.py` from the
real compiler. Payloads match the bridge's `compile` replies field for field, so
request hashes and checkpoints do not depend on which bridge produced them.
"""
import json
import struct

from parkour_solver.physics import _coefficient_tables as tables


def _flags(values, name, size=None):
    if not isinstance(values, list) or any(type(value) is not bool for value in values):
        raise ValueError(name + ' must be a list of booleans')
    if size is not None and len(values) < size:
        raise ValueError(name + ' is shorter than the movement schedule')
    return values


def _schedule(request):
    grounded, jump = request.get('grounded'), request.get('jump')
    if grounded is None or jump is None or not isinstance(request.get('inputs'), dict):
        raise ValueError('Invalid movement schedule')
    _flags(grounded, 'grounded')
    _flags(jump, 'jump')
    if not jump or len(jump) != len(grounded):
        raise ValueError('Invalid movement schedule')
    return grounded, jump


def _policy(inputs, key):
    # Absent Java policy fields are false; present ones must be JSON booleans.
    value = inputs.get(key, False)
    if type(value) is not bool:
        raise ValueError(key + ' must be boolean')
    return value


def shared(request):
    """The 1.8.9 input state machine with W held: sprint carry, jump cooldown and wall hits."""
    grounded, jump = _schedule(request)
    inputs = request['inputs']
    sprint_key, force45 = _policy(inputs, 'sprint'), _policy(inputs, 'force45')
    n = len(jump)
    sneak = request.get('sneak')
    sneak = [False] * n if sneak is None else _flags(sneak, 'sneak', n)[:n]
    ladder = request.get('ladderTicks')
    if ladder is not None:
        _flags(ladder, 'ladderTicks', n)
    vertical = request.get('vertical')
    hits = [False] * (n + 1)
    if vertical is not None:
        if not isinstance(vertical, dict) or type(vertical.get('previousHorizontalCollision')) is not bool:
            raise ValueError('Vertical state needs previousHorizontalCollision')
        hits[0] = vertical['previousHorizontalCollision']
    for contact in request.get('contacts') or []:
        axis, state = contact.get('axis', 0), contact.get('state', 0)
        if axis == 1:
            continue
        if type(state) is not int or not 0 < state <= n:
            raise ValueError('Invalid prescribed wall state')
        hits[state] = True
    if vertical is not None and (vertical.get('profile') != 'minecraft-1.8.9' or vertical.get('onGround') != grounded[0]):
        raise ValueError('Vertical profile/initial ground state disagrees with the fixed movement inputs')
    magnitude, friction, base = [], [], []
    sprinting, air_sprinting, forward, strafe, jump_velocity = [], [], [], [], []
    previous = _policy(inputs, 'incomingSprint')
    cooldown = 0
    for t in range(n):
        cooldown = max(0, cooldown - 1)
        fires = jump[t] and grounded[t] and cooldown == 0
        if fires:
            cooldown = 10
        if not jump[t]:
            cooldown = 0
        diagonal = force45 and not (jump[t] and grounded[t])
        # With W always held, the double-tap path cannot start sprint after the first
        # input and a held key reapplies sprint when its 600-tick timer expires.
        current = (previous or sprint_key) and not sneak[t] and not hits[t]
        row = tables.SHARED_ROWS[grounded[t], diagonal, sneak[t], current, previous, fires]
        magnitude.append(row[0])
        friction.append(row[1])
        base.append(row[2])
        forward.append(row[3])
        strafe.append(row[4])
        jump_velocity.append(row[5])
        sprinting.append(current)
        air_sprinting.append(previous)
        previous = current
    labels = tables.SHARED_LABELS
    result = dict(magnitude=magnitude, friction=friction, base=base,
                  movement=dict(profile=labels['profile'], compiler=labels['compiler'], horizontalCollision=hits,
                                ground=grounded[:], sprinting=sprinting, airSprinting=air_sprinting,
                                moveForward=forward, moveStrafe=strafe))
    if vertical is not None:
        # The bridge returns the request's vertical record with these two fields replaced.
        result['vertical'] = json.loads(json.dumps(vertical))
        result['vertical'].update(jumpVelocity=jump_velocity, sneak=sneak[:])
    result['model'] = labels['model']
    return result


def legacy_forward_bits(forward):
    # Gson reads a float field as the parsed double cast to float.
    return struct.unpack('<I', struct.pack('<f', forward))[0]


def legacy(request):
    """`JumpLinearModel` rows for the authored ordered-route and support-plane schedules."""
    grounded, jump = _schedule(request)
    inputs = request['inputs']
    forward, strafe = inputs.get('forward', 0.), inputs.get('strafe', 0.)
    if isinstance(forward, bool) or not isinstance(forward, (int, float)) or strafe != 0 \
            or abs(forward - tables.LEGACY_FORWARD) > tables.LEGACY_FORWARD_TOLERANCE:
        raise ValueError('Legacy coefficients cover forward movement without strafe')
    bits = legacy_forward_bits(forward)
    sprint, force45 = _policy(inputs, 'sprint'), _policy(inputs, 'force45')
    previous = _policy(inputs, 'incomingSprint')
    magnitude, friction, base = [], [], []
    for t in range(len(jump)):
        row = tables.LEGACY_ROWS[bits, grounded[t], jump[t], sprint, previous if t == 0 else sprint, force45]
        magnitude.append(row[0])
        friction.append(row[1])
        base.append(row[2])
    return dict(magnitude=magnitude, friction=friction, base=base, model=tables.LEGACY_MODEL)


def compile_request(request):
    """Answer one canonical `coefficient_request` message."""
    return shared(request) if request.get('sharedMovement') else legacy(request)
